class Solution {
  private static final long MOD = 1_000_000_007L;

  private static long pow(long b, long e) {
    long r = 1;
    for (b %= MOD; e > 0; e >>= 1) {
      if ((e & 1) == 1) r = r * b % MOD;
      b = b * b % MOD;
    }
    return r;
  }

  public int minMaxSums(int[] nums, int k) {
    int n = nums.length;
    java.util.Arrays.sort(nums);
    long[] f = new long[n + 1], inv = new long[n + 1];
    f[0] = 1;
    for (int i = 1; i <= n; i++) f[i] = f[i - 1] * i % MOD;
    inv[n] = pow(f[n], MOD - 2);
    for (int i = n; i > 0; i--) inv[i - 1] = inv[i] * i % MOD;
    long ans = 0;
    for (int i = 0; i < n; i++) {
      long ways = 0;
      for (int j = 0; j < k; j++) {
        ways += comb(f, inv, i, j) + comb(f, inv, n - 1 - i, j);
      }
      ans = (ans + nums[i] % MOD * (ways % MOD)) % MOD;
    }
    return (int) ans;
  }

  private static long comb(long[] f, long[] inv, int a, int b) {
    if (b > a) return 0;
    return f[a] * inv[b] % MOD * inv[a - b] % MOD;
  }
}
